+    expect(match?.pattern).toBe("~/.openclaw/secrets/**");
+    expect(match?.arg).toBe(absolute);
+    expect(match?.resolved).toBe(absolute);
+  });
+
+  it("blocks **/.env style pattern across nested workspaces", () => {
