+  for (const arg of candidates) {
+    if (isSkippedCandidateArg(arg)) {
+      continue;
+    }
+    if (!cwd && !isPathLikeArg(arg)) {
+      continue;
+    }
+    const expanded = expandHomePrefix(arg, { home: homeDir });
